/**
 * Batch 7: up to 60 candidate questions (Movies & TV, Music, Places, Science, Sports, Transport), of which the weakest are dropped after the preflight
 * so that Batches 6 and 7 together give 100. None is a class we already have (see batch1.ts to batch6.ts and the live bank of 250).
 * Same recipe as before (newq.ts): a Wikidata class or occupation, a minimum number of Wikipedia languages so the list has a head people know, and
 * `mustHave` = the answers a casual English-speaking player thinks of first, most obvious first. Lessons applied: see batch6.ts and docs/ANSWER_LISTS.md.
 * Build with: npx tsx src/expand/newq.ts --batch batch7 --out C:/Users/weibi/minitude/list-build/batch7
 */
import type { NewQuestion } from './newq'
import { anyKind, anyOf, characterIn, HUMAN, instanceOf, kindOf, nameIs, notDescribedAs, occupation, personForms, songsBy, strip } from './recipes'

const FILM = '?item wdt:P31/wdt:P279* wd:Q11424 .'
const FILM_GENRE = (g: string) => `${FILM} ?item wdt:P136 wd:${g} .`

const SONG = (artist: string, name: string, extra: string, mustHave: string[]): NewQuestion => ({
  id: `music-${name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')}-song`, category: 'Music', prompt: `Name a song by ${name}.`,
  rules: `Accept any song or single by ${name}, including album tracks and well-known songs written by ${name} for others (${mustHave.slice(0, 8).join(', ')}). Albums, tours and cover versions by other artists do not count.`,
  source: `Wikidata songs and musical works whose performer or composer is ${name}, known in at least 2 languages, plus the best-known ones added by hand.`,
  pattern: songsBy(artist), minSignal: 2, alsoWritten: (n) => (/^\(.*\)\s*/.test(n) ? [n.replace(/^\(.*?\)\s*/, '')] : []),
  mustHave, ...(extra ? { skip: nameIs(new RegExp(extra, 'i')) } : {}),
})

